import React, { useState, useEffect } from 'react'
import { Container, Row, Col, Table, Button, Badge } from 'reactstrap'
import { BASE_URL } from '../../utils/config'

const ManageUsers = () => {
   const [users, setUsers] = useState([])
   const [loading, setLoading] = useState(true)
   const [error, setError] = useState(null)

   useEffect(() => {
      const fetchUsers = async () => {
         try {
            const token = localStorage.getItem('token') // Lấy token khi đăng nhập

            const res = await fetch(`${BASE_URL}/users`, {
               method: 'GET',
               headers: {
                  // QUAN TRỌNG: Phải có dòng này để Backend cho phép truy cập
                  'Authorization': `Bearer ${token}` 
               }
            })

            const result = await res.json()

            if (!res.ok) {
               // Nếu res.ok là false (ví dụ lỗi 401), hiện thông báo từ Backend
               setError(result.message || "Bạn không có quyền Admin!");
            } else {
               setUsers(result.data || [])
            }
            setLoading(false)
         } catch (err) {
            setError("Lỗi kết nối Server!")
            setLoading(false)
         }
      }
      fetchUsers()
   }, [])

   const deleteUser = async (id) => {
      if (window.confirm("Bạn có chắc chắn muốn xóa người dùng này?")) {
         try {
            const token = localStorage.getItem('token')
            const res = await fetch(`${BASE_URL}/users/${id}`, {
               method: 'DELETE',
               headers: {
                  'Authorization': `Bearer ${token}`
               }
            })
            
            if (res.ok) {
               alert("Xóa thành công!")
               setUsers(prev => prev.filter(user => user._id !== id))
            } else {
               const result = await res.json()
               alert(result.message)
            }
         } catch (err) {
            alert("Lỗi máy chủ khi xóa!")
         }
      }
   }

   return (
      <section className="mt-5 pt-5">
         <Container>
            <Row>
               <Col lg='12'>
                  <div className="d-flex align-items-center justify-content-between mb-4">
                     <h3 className="fw-bold">Quản lý hệ thống (Admin)</h3>
                     <Badge color="danger" pill className="px-3 py-2">Quản trị viên</Badge>
                  </div>

                  {loading && <h4 className="text-center pt-5">Đang xác thực quyền hạn...</h4>}
                  
                  {error && (
                     <div className="alert alert-danger text-center mt-5">
                        <i className="ri-error-warning-line me-2"></i> {error}
                     </div>
                  )}

                  {!loading && !error && (
                     <Table hover responsive className="shadow-sm bg-white rounded border">
                        <thead className="bg-light">
                           <tr>
                              <th>Username</th>
                              <th>Email</th>
                              <th>Vai trò</th>
                              <th className="text-center">Thao tác</th>
                           </tr>
                        </thead>
                        <tbody>
                           {users.length > 0 ? (
                              users.map(user => (
                                 <tr key={user._id} className="align-middle">
                                    <td className="fw-bold">{user.username}</td>
                                    <td>{user.email}</td>
                                    <td>
                                       <Badge color={user.role === 'admin' ? 'danger' : 'success'} pill>
                                          {user.role}
                                       </Badge>
                                    </td>
                                    <td className="text-center">
                                       <Button color="danger" outline size="sm" onClick={() => deleteUser(user._id)}>
                                          <i className="ri-delete-bin-line"></i>
                                       </Button>
                                    </td>
                                 </tr>
                              ))
                           ) : (
                              <tr>
                                 <td colSpan="4" className="text-center py-4">Chưa có người dùng nào.</td>
                              </tr>
                           )}
                        </tbody>
                     </Table>
                  )}
               </Col>
            </Row>
         </Container>
      </section>
   )
}

export default ManageUsers
